-- PDF curriculum. Stable IDs and answer indices retain historical evidence.
begin;
update public.topics set content=content||jsonb_build_object('title',case when content->'title'='"Make sense of place value"'::jsonb then '"Натуральные числа: разряды, классы, чтение и запись больших чисел"'::jsonb else content->'title' end,'objective',case when content->'objective'='"Read and build whole numbers using place value."'::jsonb then '"Читаем и записываем натуральные числа по разрядам."'::jsonb else content->'objective' end,'lesson',case when content->'lesson'='"Every digit has a place. From right to left, the places are ones, tens, hundreds and thousands. Moving one place to the left makes a digit’s value ten times larger."'::jsonb then '"У каждой цифры есть разряд: справа налево идут единицы, десятки, сотни и тысячи. При переходе на один разряд влево значение цифры увеличивается в десять раз."'::jsonb else content->'lesson' end,'example',case when content->'example'='"In 3,742, the 7 means 7 hundreds, or 700. The whole number is 3,000 + 700 + 40 + 2."'::jsonb then '"В числе 3 742 цифра 7 означает 7 сотен, то есть 700. Число можно записать как 3 000 + 700 + 40 + 2."'::jsonb else content->'example' end)||'{"sectionId":"section-01","order":1}'::jsonb where id='place-value';
