update public.topics set content=content||jsonb_build_object('title',case when content->'title'='"Confident with operations"'::jsonb then '"Порядок действий и роль скобок"'::jsonb else content->'title' end,'objective',case when content->'objective'='"Use multiplication before addition in a calculation."'::jsonb then '"Выполняем умножение раньше сложения."'::jsonb else content->'objective' end,'lesson',case when content->'lesson'='"Order of operations helps everyone read a calculation in the same way. First calculate inside brackets. Then multiply or divide. Finally add or subtract."'::jsonb then '"Порядок действий позволяет всем одинаково понимать выражение. Сначала выполните действия в скобках, затем умножение и деление, в конце — сложение и вычитание."'::jsonb else content->'lesson' end,'example',case when content->'example'='"For 5 + 3 × 4, multiply first: 3 × 4 = 12. Then 5 + 12 = 17."'::jsonb then '"В выражении 5 + 3 × 4 сначала умножаем: 3 × 4 = 12. Затем 5 + 12 = 17."'::jsonb else content->'example' end)||'{"sectionId":"section-01","order":6}'::jsonb where id='operations';
