update public.topics set content=content||jsonb_build_object('title',case when content->'title'='"Keep equations balanced"'::jsonb then '"Уравнение как равенство с неизвестным; что значит «решить» и «проверить корень»"'::jsonb else content->'title' end,'objective',case when content->'objective'='"Solve a one-step equation using the inverse operation."'::jsonb then '"Решаем уравнение с помощью обратного действия."'::jsonb else content->'objective' end,'lesson',case when content->'lesson'='"An equation is a balance. Do the same operation to both sides to keep it equal. Undo addition with subtraction, and multiplication with division."'::jsonb then '"Уравнение похоже на весы. Выполняйте одинаковые действия с обеими частями, чтобы равенство сохранилось. Сложение отменяется вычитанием, а умножение — делением."'::jsonb else content->'lesson' end,'example',case when content->'example'='"x + 6 = 14. Subtract 6 from both sides: x = 8. Check: 8 + 6 = 14."'::jsonb then '"x + 6 = 14. Вычтем 6 из обеих частей: x = 8. Проверка: 8 + 6 = 14."'::jsonb else content->'example' end)||'{"sectionId":"section-03","order":14}'::jsonb where id='equations';
