update public.topics set content=content||jsonb_build_object('title',case when content->'title'='"Equivalent fractions"'::jsonb then '"Основное свойство дроби: сокращение и приведение к новому знаменателю"'::jsonb else content->'title' end,'objective',case when content->'objective'='"Find fractions that name the same amount."'::jsonb then '"Находим дроби, которые обозначают одну и ту же величину."'::jsonb else content->'objective' end,'lesson',case when content->'lesson'='"A fraction describes equal parts of a whole. Multiply or divide the top and bottom by the same non-zero number to keep the amount unchanged."'::jsonb then '"Дробь обозначает равные части целого. Если умножить или разделить числитель и знаменатель на одно и то же ненулевое число, величина дроби не изменится."'::jsonb else content->'lesson' end,'example',case when content->'example'='"1/2 = 2/4 = 3/6. Imagine the same half of a loaf cut into more, smaller pieces. The number of pieces changes, but the amount of bread does not."'::jsonb then '"1/2 = 2/4 = 3/6. Представьте, что одну половину хлеба разрезали на несколько мелких кусочков. Кусочков стало больше, но количество хлеба осталось прежним."'::jsonb else content->'example' end)||'{"sectionId":"section-05","order":23}'::jsonb where id='equivalent';
