update public.topics set content=content||jsonb_build_object('title',case when content->'title'='"Add unlike fractions"'::jsonb then '"Сложение и вычитание дробей"'::jsonb else content->'title' end,'objective',case when content->'objective'='"Add fractions by finding a common denominator."'::jsonb then '"Складываем дроби, приводя их к общему знаменателю."'::jsonb else content->'objective' end,'lesson',case when content->'lesson'='"You can only count fractional pieces together when they have the same size. Rename fractions using a common denominator, add the numerators, and keep the denominator."'::jsonb then '"Складывать части можно, когда они одинакового размера. Приведите дроби к общему знаменателю, сложите числители, а знаменатель оставьте прежним."'::jsonb else content->'lesson' end,'example',case when content->'example'='"1/2 + 1/4 = 2/4 + 1/4 = 3/4. The denominator stays 4 because the pieces are still quarters."'::jsonb then '"1/2 + 1/4 = 2/4 + 1/4 = 3/4. Знаменатель остаётся равным 4, потому что мы считаем четверти."'::jsonb else content->'example' end)||'{"sectionId":"section-05","order":25}'::jsonb where id='add-fractions';
