update public.topics set content=content||jsonb_build_object('title',case when content->'title'='"Understanding the mean"'::jsonb then '"Среднее арифметическое"'::jsonb else content->'title' end,'objective',case when content->'objective'='"Find the mean of a small data set."'::jsonb then '"Находим среднее арифметическое нескольких чисел."'::jsonb else content->'objective' end,'lesson',case when content->'lesson'='"The mean is a fair-share average. Add the values and divide by how many values there are. Include zero values when they are part of the data."'::jsonb then '"Чтобы найти среднее арифметическое, сложите все значения и разделите сумму на их количество. Нули тоже учитываются, если они есть в наборе данных."'::jsonb else content->'lesson' end,'example',case when content->'example'='"The mean of 2, 4 and 9 is (2 + 4 + 9) ÷ 3 = 5."'::jsonb then '"Среднее арифметическое чисел 2, 4 и 9: (2 + 4 + 9) ÷ 3 = 5."'::jsonb else content->'example' end)||'{"sectionId":"section-06","order":32}'::jsonb where id='averages';
