update public.topics set content=content||jsonb_build_object('title',case when content->'title'='"Ratios in everyday life"'::jsonb then '"Отношение двух величин: что оно показывает"'::jsonb else content->'title' end,'objective',case when content->'objective'='"Scale a ratio while keeping its relationship."'::jsonb then '"Изменяем количества, сохраняя их отношение."'::jsonb else content->'objective' end,'lesson',case when content->'lesson'='"A ratio compares amounts. If a drink uses 1 part juice to 3 parts water, each batch uses four parts in total. Scale both quantities by the same number."'::jsonb then '"Отношение сравнивает количества. Если напиток состоит из 1 части сока и 3 частей воды, всего получается 4 части. Чтобы сохранить вкус, увеличивайте оба количества в одинаковое число раз."'::jsonb else content->'lesson' end,'example',case when content->'example'='"For 2 cups of juice at a 1 : 3 ratio, use 6 cups of water. The ratio stays 2 : 6 = 1 : 3."'::jsonb then '"На 2 стакана сока при отношении 1 : 3 нужно 6 стаканов воды. Отношение сохраняется: 2 : 6 = 1 : 3."'::jsonb else content->'example' end)||'{"sectionId":"section-07","order":34}'::jsonb where id='ratios';
