update public.topics set content=content||jsonb_build_object('title',case when content->'title'='"Covering a surface"'::jsonb then '"Площадь прямоугольника"'::jsonb else content->'title' end,'objective',case when content->'objective'='"Calculate rectangle area in square units."'::jsonb then '"Вычисляем площадь прямоугольника в квадратных единицах."'::jsonb else content->'objective' end,'lesson',case when content->'lesson'='"Area measures how much flat space a shape covers. A rectangle can be filled with rows of unit squares. Multiply its length by its width."'::jsonb then '"Площадь показывает, сколько места занимает фигура на плоскости. Прямоугольник можно заполнить рядами единичных квадратов. Для нахождения площади умножьте длину на ширину."'::jsonb else content->'lesson' end,'example',case when content->'example'='"A 5 cm by 3 cm rectangle has 3 rows of 5 squares: 15 cm². Perimeter and area measure different things."'::jsonb then '"В прямоугольнике 5 см на 3 см помещается 3 ряда по 5 квадратов: 15 см². Периметр измеряет длину границы, а площадь — размер поверхности."'::jsonb else content->'example' end)||'{}'::jsonb where id='area';
