update public.topics set content=content||jsonb_build_object('title',case when content->'title'='"How likely is it?"'::jsonb then '"Вероятность события"'::jsonb else content->'title' end,'objective',case when content->'objective'='"Express the probability of an equally likely outcome."'::jsonb then '"Находим вероятность при равновозможных исходах."'::jsonb else content->'objective' end,'lesson',case when content->'lesson'='"Probability compares the number of outcomes you want with all possible equally likely outcomes. An impossible event has probability 0; a certain event has probability 1."'::jsonb then '"Вероятность — отношение числа благоприятных исходов к общему числу равновозможных исходов. Вероятность невозможного события равна 0, а достоверного — 1."'::jsonb else content->'lesson' end,'example',case when content->'example'='"A bag has 3 blue and 2 red counters. For a random pick, P(blue) = 3/5 because 3 of the 5 counters are blue."'::jsonb then '"В мешке 3 синие и 2 красные фишки. Вероятность случайно достать синюю: 3/5, потому что из 5 фишек 3 — синие."'::jsonb else content->'example' end)||'{}'::jsonb where id='probability';
update public.topics set content=jsonb_set(content,'{checks,0}','{"id":"probability-check-1","prompt":"В мешке 3 синих и 3 красные фишки. Какова вероятность случайно достать синюю?","choices":["4/6","3/7","1/6","3/6"],"answer":3,"explanation":"Всего 6 фишек, из них 3 — синие. Вероятность равна 3/6.","hint":"Разделите число синих фишек на общее число фишек."}'::jsonb) where id='probability' and content#>'{checks,0}'='{"id":"probability-check-1","prompt":"A bag has 3 blue and 3 red counters. What is the probability of picking blue?","choices":["4/6","3/7","1/6","3/6"],"answer":3,"explanation":"There are 6 counters in all, and 3 are blue. Probability = 3/6.","hint":"Put the number of blue counters over the total number of counters."}'::jsonb;
